        // full state kalman update
        chol(ekf_S_chol, S, ekf_S_iDiag, N_MEASUREMENTS_POS);
        for (int i = 0; i < N_STATES; i++) {
            float k_row[N_MEASUREMENTS_POS];
            chol_solve(ekf_S_chol, ekf_S_iDiag, N_MEASUREMENTS_POS, (HP+(i*N_MEASUREMENTS_POS)), k_row);
            for (int j = 0; j < N_MEASUREMENTS_POS; j++) {
                K[i + j*N_STATES] = k_row[j];
            }
        }

        // UPDATE STEP X_new = ...
        tmp[0] = -X[0] + Z[0];
        tmp[1] = -X[1] + Z[1];
        tmp[2] = -X[2] + Z[2];
        X_new[0] = K[0]*tmp[0] + K[22]*tmp[1] + K[44]*tmp[2] + X[0];
