    float p3d2_z = param[12];
    float p3d3_x = param[13];
    float p3d3_y = param[14];
    float p3d3_z = param[15];

    // h
    tmp[0] = sinf(X[20]);
    tmp[1] = -X[2];
    tmp[2] = -X[0];
    tmp[3] = p3d0_x + tmp[2];
    tmp[4] = powf(powf(X[6], 2) + powf(X[7], 2) + powf(X[8], 2) + powf(X[9], 2), -1.0/2.0);
    tmp[5] = X[7]*tmp[4];
    tmp[6] = -X[1];
    tmp[7] = p3d0_y + tmp[6];
    tmp[8] = X[8]*tmp[4];
    tmp[9] = p3d0_z + tmp[1];
    tmp[10] = X[9]*tmp[4];
    tmp[11] = tmp[10]*tmp[9] + tmp[3]*tmp[5] + tmp[7]*tmp[8];
    tmp[12] = X[6]*tmp[4];
    tmp[13] = tmp[4]*tmp[7];
    tmp[14] = -X[7]*tmp[13] + tmp[12]*tmp[9] + tmp[3]*tmp[8];
    tmp[15] = tmp[12]*tmp[3];
    tmp[16] = X[9]*tmp[13];
    tmp[17] = tmp[8]*tmp[9];
    tmp[18] = tmp[15] + tmp[16] - tmp[17];
    tmp[19] = -tmp[10]*tmp[3] + tmp[12]*tmp[7] + tmp[5]*tmp[9];
    tmp[20] = tmp[10]*tmp[11] + tmp[12]*tmp[14] + tmp[18]*tmp[8] - tmp[19]*tmp[5] + tmp[1];
    tmp[21] = -X[16];
    tmp[22] = tmp[10]*tmp[19] + tmp[11]*tmp[5] + tmp[12]*tmp[18] - tmp[14]*tmp[8] + tmp[21];
    tmp[23] = cosf(X[21]);
    tmp[24] = cosf(X[20]);
    tmp[25] = tmp[23]*tmp[24];
    tmp[26] = -X[17];
    tmp[27] = tmp[10]*(-tmp[15] - tmp[16] + tmp[17]) + tmp[11]*tmp[8] + tmp[12]*tmp[19] + tmp[14]*tmp[5] + tmp[26];
    tmp[28] = sinf(X[21]);
    tmp[29] = tmp[24]*tmp[28];
    tmp[30] = 1.0/(-tmp[0]*tmp[20] + tmp[22]*tmp[25] + tmp[27]*tmp[29]);
    tmp[31] = sinf(X[19]);
    tmp[32] = tmp[20]*tmp[24];
    tmp[33] = cosf(X[19]);
    tmp[34] = tmp[23]*tmp[33];
    tmp[35] = tmp[28]*tmp[31];
    tmp[36] = tmp[0]*tmp[35] + tmp[34];
    tmp[37] = tmp[28]*tmp[33];
    tmp[38] = tmp[23]*tmp[31];
    tmp[39] = tmp[0]*tmp[38] - tmp[37];
    tmp[40] = tmp[0]*tmp[34] + tmp[35];
    tmp[41] = tmp[0]*tmp[37] - tmp[38];
